python -m py_compile api.py && python - <<'PY'
import api
api.process = lambda data: data
assert api.handle_request({'name': 'value'}) == {'name': 'value'}
for invalid in (None, [], 'payload'):
    try:
        api.handle_request(invalid)
    except TypeError:
        pass
    else:
        raise AssertionError(f'accepted invalid payload: {invalid!r}')
try:
    api.handle_request({1: 'value'})
except TypeError:
    pass
else:
    raise AssertionError('accepted a non-string key')
print('validation checks passed')
